use crate::layout::Rect;use notepad_core::Note;#[derive(Debug,Clone,Default)]pub struct SidebarState{pub query:String,pub selected_note:Option<i64>,pub notes:Vec<Note>}impl SidebarState{pub fn set_notes(&mut self,n:Vec<Note>){self.notes=n;if self.selected_note.is_some_and(|id|!self.notes.iter().any(|n|n.id==id)){self.selected_note=None}}pub fn card_rect(&self,b:Rect,i:usize)->Rect{Rect::new(b.x+12,b.y+54+i as i32*68,(b.w-24).max(0),58)}}
